pydough_code:
sergey_levine_venue = scholar.authors.WHERE(authorname == "sergey levine").CALCULATE(
    authorid=authorid
).write.paper.ORDER_BY(year.DESC()).TOP_K(1, by=year.DESC()).venue.CALCULATE(
    venue_name=venuename
)

