pydough_code:
first_deep_learning_paper = scholar.paperkeyphrases.WHERE(
    keyphrase.keyphrasename == "deep learning"
).paper.ORDER_BY(year.ASC()).TOP_K(1, by=year.ASC()).CALCULATE(
    title=title,
    year=year
)

