pydough_code:
most_employees = hirings.CALCULATE(
    shop_name=shop.name
).PARTITION(name="shop_partition", by=shop_name).CALCULATE(
    employee_count=COUNT(hirings),
    shop_name=shop_name
).TOP_K(1, by=employee_count.DESC()).CALCULATE(shop_name=shop_name)

