pydough_code:
hvj_ds_papers = academic.authors.WHERE(
    (name == " H. V. Jagadish ") | (name == " Divesh Srivastava ")
).write.publication.WHERE(
    CAST(citation_num, 'INT') > 200
).CALCULATE(title=title)

