pydough_code:
papers_before_2000 = academic.authors.WHERE(
    (name == " H. V. Jagadish ") | (name == " Divesh Srivastava ")
).write.publication.WHERE(
    CAST(year, 'INT') < 2000
).CALCULATE(
    title=title
)

