Database Schema:
{"aan_1": {"affiliations": {"type": "simple_table", "table_path": "main.Affiliation", "unique_properties": ["affiliation_id"], "properties": {"affiliation_id": {"type": "table_column", "column_name": "affiliation_id", "data_type": "int64"}, "name": {"type": "table_column", "column_name": "name", "data_type": "string"}, "address": {"type": "table_column", "column_name": "address", "data_type": "string"}}}, "authors": {"type": "simple_table", "table_path": "main.Author", "unique_properties": ["author_id"], "properties": {"author_id": {"type": "table_column", "column_name": "author_id", "data_type": "int64"}, "name": {"type": "table_column", "column_name": "name", "data_type": "string"}, "email": {"type": "table_column", "column_name": "email", "data_type": "string"}}}, "author_lists": {"type": "simple_table", "table_path": "main.Author_list", "unique_properties": [["paper_id", "author_id"]], "properties": {"paper_id": {"type": "table_column", "column_name": "paper_id", "data_type": "string"}, "author_id": {"type": "table_column", "column_name": "author_id", "data_type": "int64"}, "affiliation_id": {"type": "table_column", "column_name": "affiliation_id", "data_type": "int64"}, "affiliation": {"type": "simple_join", "other_collection_name": "affiliations", "singular": true, "no_collisions": false, "keys": {"affiliation_id": ["affiliation_id"]}, "reverse_relationship_name": "author_lists"}, "author": {"type": "simple_join", "other_collection_name": "authors", "singular": true, "no_collisions": false, "keys": {"author_id": ["author_id"]}, "reverse_relationship_name": "author_lists"}, "paper": {"type": "simple_join", "other_collection_name": "papers", "singular": true, "no_collisions": false, "keys": {"paper_id": ["paper_id"]}, "reverse_relationship_name": "author_lists"}}}, "citations": {"type": "simple_table", "table_path": "main.Citation", "unique_properties": [["paper_id", "cited_paper_id"]], "properties": {"paper_id": {"type": "table_column", "column_name": "paper_id", "data_type": "string"}, "cited_paper_id": {"type": "table_column", "column_name": "cited_paper_id", "data_type": "string"}, "paper": {"type": "simple_join", "other_collection_name": "papers", "singular": true, "no_collisions": false, "keys": {"paper_id": ["paper_id"]}, "reverse_relationship_name": "citations"}}}, "papers": {"type": "simple_table", "table_path": "main.Paper", "unique_properties": ["paper_id"], "properties": {"paper_id": {"type": "table_column", "column_name": "paper_id", "data_type": "string"}, "title": {"type": "table_column", "column_name": "title", "data_type": "string"}, "venue": {"type": "table_column", "column_name": "venue", "data_type": "string"}, "year": {"type": "table_column", "column_name": "year", "data_type": "int64"}}}}}

pydough_code:
top_affiliations = aan_1.author_lists.WHERE(paper.year == 2009).CALCULATE(
    affiliation_name = affiliation.name
).PARTITION(name='affiliation_partition', by=affiliation_name).CALCULATE(
    affiliation_name = affiliation_name,
    paper_count = COUNT(author_lists)
).TOP_K(3, by=paper_count.DESC()).CALCULATE(affiliation_name = affiliation_name)

