pydough_code:
pet_groomers_reviews = yelp.businesses.WHERE(
    (businesses.categories.category_name == "Pet Groomers") & (CAST(review_count, 'INT') > 100)
).reviews.CALCULATE(rid=rid, business_id=business_id, user_id=user_id, rating=rating, text=text, year=year, month=month)

